40	// reuseUnixSocket copies and reuses the unix domain socket (UDS) if we already
41	// have it open; if not, unlink it so we can have it.
42	// No-op if not a unix network.
43	func reuseUnixSocket(network, addr string) (any, error) {
44		socketKey := listenerKey(network, addr)
45	
46		socket, exists := unixSockets[socketKey]
47		if exists {
48			// make copy of file descriptor
49			socketFile, err := socket.File() // does dup() deep down
50			if err != nil {
51				return nil, err
52			}
53	
54			// use copied fd to make new Listener or PacketConn, then replace
55			// it in the map so that future copies always come from the most
56			// recent fd (as the previous ones will be closed, and we'd get
57			// "use of closed network connection" errors) -- note that we
58			// preserve the *pointer* to the counter (not just the value) so
59			// that all socket wrappers will refer to the same value
60			switch unixSocket := socket.(type) {
61			case *unixListener:
62				ln, err := net.FileListener(socketFile)
63				if err != nil {
64					return nil, err
65				}
66				unixSocket.count.Add(1)
67				unixSockets[socketKey] = &unixListener{ln.(*net.UnixListener), socketKey, unixSocket.count}
68	
69			case *unixConn:
70				pc, err := net.FilePacketConn(socketFile)
71				if err != nil {
72					return nil, err
73				}
74				unixSocket.count.Add(1)
75				unixSockets[socketKey] = &unixConn{pc.(*net.UnixConn), socketKey, unixSocket.count}
76			}
77	
78			return unixSockets[socketKey], nil
79		}
80	
81		// from what I can tell after some quick research, it's quite common for programs to
82		// leave their socket file behind after they close, so the typical pattern is to
83		// unlink it before you bind to it -- this is often crucial if the last program using
84		// it was killed forcefully without a chance to clean up the socket, but there is a
85		// race, as the comment in net.UnixListener.close() explains... oh well, I guess?
86		if err := syscall.Unlink(addr); err != nil && !errors.Is(err, fs.ErrNotExist) {
87			return nil, err
88		}
89	
90		return nil, nil
91	}
92	
93	// listenReusable creates a new listener for the given network and address, and adds it to listenerPool.
94	func listenReusable(ctx context.Context, lnKey string, network, address string, config net.ListenConfig) (any, error) {
95		// even though SO_REUSEPORT lets us bind the socket multiple times,
96		// we still put it in the listenerPool so we can count how many
97		// configs are using this socket; necessary to ensure we can know
98		// whether to enforce shutdown delays, for example (see #5393).
99		var (
100			ln         io.Closer
101			err        error
102			socketFile *os.File
103		)
104	
105		fd := slices.Contains([]string{"fd", "fdgram"}, network)
106		if fd {
107			socketFd, err := strconv.ParseUint(address, 0, strconv.IntSize)
108			if err != nil {
109				return nil, fmt.Errorf("invalid file descriptor: %v", err)
110			}
111	
112			func() {
113				socketFilesMu.Lock()
114				defer socketFilesMu.Unlock()
115	
116				socketFdWide := uintptr(socketFd)
117				var ok bool
118	
119				socketFile, ok = socketFiles[socketFdWide]
120	
121				if !ok {
122					socketFile = os.NewFile(socketFdWide, lnKey)
123					if socketFile != nil {
124						socketFiles[socketFdWide] = socketFile
125					}
126				}
127			}()
128	
129			if socketFile == nil {
130				return nil, fmt.Errorf("invalid socket file descriptor: %d", socketFd)
131			}
132		} else {
133			// wrap any Control function set by the user so we can also add our reusePort control without clobbering theirs
134			oldControl := config.Control
135			config.Control = func(network, address string, c syscall.RawConn) error {
136				if oldControl != nil {
137					if err := oldControl(network, address, c); err != nil {
138						return err
139					}
140				}
141				return reusePort(network, address, c)
142			}
143		}
144	
145		datagram := slices.Contains([]string{"udp", "udp4", "udp6", "unixgram", "fdgram"}, network)
146		if datagram {
147			if fd {
148				ln, err = net.FilePacketConn(socketFile)
149			} else {
150				ln, err = config.ListenPacket(ctx, network, address)
151			}
152		} else {
153			if fd {
154				ln, err = net.FileListener(socketFile)
155			} else {
156				ln, err = config.Listen(ctx, network, address)
157			}
158		}
159	
160		if err == nil {
161			listenerPool.LoadOrStore(lnKey, nil)
