283	// sharedPacketConn is like sharedListener, but for net.PacketConns.
284	type sharedPacketConn struct {
285		net.PacketConn
286		key string
287	}
288	
289	// Destruct closes the underlying socket.
290	func (spc *sharedPacketConn) Destruct() error {
291		return spc.PacketConn.Close()
292	}
293	
294	// Unwrap returns the underlying socket
295	func (spc *sharedPacketConn) Unwrap() net.PacketConn {
296		return spc.PacketConn
297	}
298	
299	// Interface guards (see https://github.com/caddyserver/caddy/issues/3998)
300	var (
301		_ (interface {
302			Unwrap() net.PacketConn
303		}) = (*fakeClosePacketConn)(nil)
304	)
305	
306	// socketFiles is a fd -> *os.File map used to make a FileListener/FilePacketConn from a socket file descriptor.
307	var socketFiles = map[uintptr]*os.File{}
308	
309	// socketFilesMu synchronizes socketFiles insertions
310	var socketFilesMu sync.Mutex
