===== a/checks/config_load_parse.py
import json, os, socket, subprocess, sys, tempfile, threading, time
from http.client import HTTPConnection
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.error import HTTPError
from urllib.request import Request, urlopen

# Coverage: parse failures (truncated object/string, schema type mismatch,
# trailing bytes) -> reject with API JSON error -> exact last-good /version;
# in-flight /hold -> complete entirely with old response; valid A/B loads
# alternate after failures. A wrong implementation that clears config before
# parsing, accepts trailing bytes, leaks site errors, or mixes in-flight
# responses fails the corresponding assertion below.
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

class HoldHandler(BaseHTTPRequestHandler):
    release = threading.Event()
    def do_GET(self):
        if self.path == '/hold':
            self.send_response(200)
            self.send_header('X-Upstream', 'A')
            self.end_headers()
            self.wfile.write(b'prefix')
            self.wfile.flush()
            HoldHandler.release.wait(10)
            self.wfile.write(b'-suffix')
            self.wfile.flush()
        else:
            self.send_error(404)
    def log_message(self, *args):
        pass

def headers_without_date(h):
    return {k.lower(): tuple(v) for k, v in h.items() if k.lower() != 'date'}

