//go:build !windows

package integration

import (
	"bytes"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"testing"
	"time"
)

// This file pins the observable readiness and failure boundaries of the only
// supported foreground entry point:
//
//	caddy run --config <file> --adapter caddyfile
//
// Acceptance relies exclusively on externally observable signals - the
// process exit status, stderr and plain HTTP requests - never on internal
// state. The three outcomes an automation caller must distinguish are:
//
//   - not ready yet: the process is alive but the port is not serving the
//     configured contract yet (connection refused / reset);
//   - startup failed: the process exits non-zero in bounded time, stderr
//     carries the parse/initialisation/bind root cause and no listener
//     remains;
//   - business error: the service is ready, stays up and merely answers a
//     request with an upstream-generated 5xx.
//
// In addition, a request held open in the previous generation across a
// stop/restart on the same address must finish on the generation that
// accepted it, while the new generation answers new requests with only its
// own markers; repeated stops, failed starts and restarts must all be
// deterministic and must leave the address reusable.

const (
	rrHoldPrefix = "A-inflight-prefix--"
	rrHoldSuffix = "A-inflight-suffix--"
	rrVersionA   = "A\n"
	rrVersionB   = "B\n"
)

// rrUpstream is a test-controlled HTTP/1.1 upstream. /hold answers with a
// chunked 200, flushes a marker header and body prefix, then parks the
// hijacked connection until the test releases it. /biz500 answers with a
// plain 500 so business errors can be told apart from startup failures.
type rrUpstream struct {
	ln net.Listener

	mu   sync.Mutex
	held []net.Conn
}

func newRRUpstream(t *testing.T) *rrUpstream {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen for upstream: %v", err)
	}
	u := &rrUpstream{ln: ln}
	srv := &http.Server{Handler: http.HandlerFunc(u.handle)}
	go srv.Serve(ln)
	t.Cleanup(func() { srv.Close(); ln.Close() })
	return u
}

func (u *rrUpstream) addr() string { return u.ln.Addr().String() }

func (u *rrUpstream) releaseAll() {
	u.mu.Lock()
	conns := u.held
	u.held = nil
	u.mu.Unlock()
	for _, conn := range conns {
		fmt.Fprintf(conn, "%x\r\n%s\r\n", len(rrHoldSuffix), rrHoldSuffix)
		_, _ = io.WriteString(conn, "0\r\n\r\n")
		_ = conn.Close()
	}
}

func (u *rrUpstream) handle(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/hold":
		conn, rw, err := w.(http.Hijacker).Hijack()
		if err != nil {
			panic(err)
		}
		_, _ = io.WriteString(rw,
			"HTTP/1.1 200 OK\r\n"+
				"X-Hold-Marker: hold-A\r\n"+
				"Transfer-Encoding: chunked\r\n"+
				"\r\n")
		fmt.Fprintf(rw, "%x\r\n%s\r\n", len(rrHoldPrefix), rrHoldPrefix)
		_ = rw.Flush()

		u.mu.Lock()
		u.held = append(u.held, conn)
		u.mu.Unlock()

		// park until releaseAll closes the connection; after a Hijack the
		// stdlib server does not touch this connection anymore
		_, _ = io.Copy(io.Discard, rw)

	case "/biz500":
		w.Header().Set("X-Up-Err", "boom")
		w.Header().Set("Content-Type", "text/plain")
		w.WriteHeader(http.StatusInternalServerError)
		_, _ = io.WriteString(w, "up-500")

	default:
		w.WriteHeader(http.StatusNotFound)
	}
}

// rrProc is one running `caddy run` foreground process.
type rrProc struct {
	cmd     *exec.Cmd
	logPath string
	done    chan error
}

func rrFreePort(t *testing.T) int {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("allocating port: %v", err)
	}
	defer ln.Close()
	return ln.Addr().(*net.TCPAddr).Port
}

// rrCaddyfile builds a Caddyfile whose only site serves /version with the
// given status, X-Version marker and exact body, proxies /hold (and the
// catch-all) to the test upstream, and keeps the admin endpoint disabled so
// the foreground process is controlled entirely via signals.
func rrCaddyfile(siteAddr, upstream, version string) string {
	return fmt.Sprintf(`{
	skip_install_trust
	admin off
}
http://%s {
	handle /version {
		header X-Version %s
		respond %q
	}
	reverse_proxy %s
}
`, siteAddr, version, version, upstream)
}

func rrWriteConfig(t *testing.T, dir, name, contents string) string {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(contents), 0o600); err != nil {
		t.Fatalf("writing %s: %v", name, err)
	}
	return path
}

func rrStart(t *testing.T, bin, cfgPath, runDir string) *rrProc {
	t.Helper()
	logFile, err := os.Create(filepath.Join(runDir, strings.TrimSuffix(filepath.Base(cfgPath), filepath.Ext(cfgPath))+".log"))
	if err != nil {
		t.Fatalf("creating log file: %v", err)
	}
	cmd := exec.Command(bin, "run", "--config", cfgPath, "--adapter", "caddyfile")
	cmd.Stdout = logFile
	cmd.Stderr = logFile
	cmd.Env = isolatedCaddyEnv(runDir, "state")
	if err := cmd.Start(); err != nil {
		logFile.Close()
		t.Fatalf("starting caddy: %v", err)
	}
	p := &rrProc{cmd: cmd, logPath: logFile.Name(), done: make(chan error, 1)}
	go func() { p.done <- cmd.Wait(); logFile.Close() }()
	return p
}

func (p *rrProc) alive() bool {
	select {
	case <-p.done:
		return false
	default:
		return true
	}
}

func (p *rrProc) tail(t *testing.T) string {
	t.Helper()
	b, err := os.ReadFile(p.logPath)
	if err != nil {
		return "(unreadable log)"
	}
	const max = 3000
	if len(b) > max {
		b = b[len(b)-max:]
	}
	return string(b)
}

// terminate sends SIGTERM; a second call on an already-finished process must
// be a harmless, deterministic no-op rather than an error.
func (p *rrProc) terminate() error { return p.cmd.Process.Signal(syscall.SIGTERM) }

func (p *rrProc) waitExit(t *testing.T, timeout time.Duration, label string) {
	t.Helper()
	select {
	case <-p.done:
	case <-time.After(timeout):
		_ = p.cmd.Process.Kill()
		t.Fatalf("%s: process did not exit within %s\n%s", label, timeout, p.tail(t))
	}
}

// rrExpectReady polls until the full readiness contract holds: the process is
// alive, the port serves, and /version answers with exactly the expected
// status, X-Version header and body. A mere successful process creation or a
// briefly-open port never counts; a connection failure while the process is
// still starting is treated as the startup phase, not an HTTP error.
func rrExpectReady(t *testing.T, p *rrProc, baseURL, wantVersion string) {
	t.Helper()
	client := &http.Client{Timeout: 2 * time.Second}
	deadline := time.Now().Add(60 * time.Second)
	var lastOdd string
	for time.Now().Before(deadline) {
		if !p.alive() {
			t.Fatalf("process exited before becoming ready\n%s", p.tail(t))
		}
		resp, err := client.Get(baseURL + "/version")
		if err != nil {
			// connection refused/reset while the server is coming up is the
			// "not ready yet" phase; keep waiting
			time.Sleep(50 * time.Millisecond)
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode == http.StatusOK &&
			resp.Header.Get("X-Version") == wantVersion &&
			string(body) == wantVersion+"\n" {
			return
		}
		lastOdd = fmt.Sprintf("status=%d X-Version=%q body=%q",
			resp.StatusCode, resp.Header.Get("X-Version"), string(body))
		time.Sleep(50 * time.Millisecond)
	}
	t.Fatalf("did not reach readiness contract (200 + X-Version %q + %q body): %s\n%s",
		wantVersion, wantVersion+"\n", lastOdd, p.tail(t))
}

// rrExpectStartupFailure runs a config that must not start: the process has
// to exit non-zero in bounded time, stderr must name the parse/init/bind
// root cause, and afterwards nothing may accept on the site address.
func rrExpectStartupFailure(t *testing.T, bin, cfgPath, runDir, siteHostPort string, rootCauses ...string) {
	t.Helper()
	p := rrStart(t, bin, cfgPath, runDir)
	p.waitExit(t, 20*time.Second, "invalid config startup")
	if err := <-p.done; err == nil {
		t.Fatalf("invalid config exited successfully; want non-zero\n%s", p.tail(t))
	}

	log := p.tail(t)
	for _, cause := range rootCauses {
		if strings.Contains(log, cause) {
			return
		}
	}
	t.Fatalf("stderr does not name any root cause %v:\n%s", rootCauses, log)
}

func rrAssertPortClosed(t *testing.T, hostPort string) {
	t.Helper()
	conn, err := net.DialTimeout("tcp", hostPort, time.Second)
	if err == nil {
		conn.Close()
		t.Fatalf("%s still accepts connections after startup failure", hostPort)
	}
}

// TestCaddyRunReadinessAndFailureBoundaries drives `caddy run
// --adapter caddyfile` as an automation caller would and asserts the three
// distinguishable outcomes plus cross-restart isolation.
func TestCaddyRunReadinessAndFailureBoundaries(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping subprocess boundaries test in short mode")
	}
	bin := buildCaddyBinary(t)
	upstream := newRRUpstream(t)

	sitePort := rrFreePort(t)
	siteHostPort := fmt.Sprintf("127.0.0.1:%d", sitePort)
	siteAddr := siteHostPort
	baseURL := "http://" + siteHostPort

	runDir := t.TempDir()

	cfgA := rrWriteConfig(t, runDir, "a.Caddyfile", rrCaddyfile(siteAddr, upstream.addr(), "A"))
	cfgB := rrWriteConfig(t, runDir, "b.Caddyfile", rrCaddyfile(siteAddr, upstream.addr(), "B"))

	// 1. readiness + business 500 is not a startup failure.
	t.Run("readiness contract and business 500", func(t *testing.T) {
		a := rrStart(t, bin, cfgA, runDir)
		t.Cleanup(func() {
			if a.alive() {
				_ = a.terminate()
				a.waitExit(t, 10*time.Second, "cleanup")
			}
		})
		rrExpectReady(t, a, baseURL, "A")

		resp, err := http.Get(baseURL + "/biz500")
		if err != nil {
			t.Fatalf("GET /biz500: %v", err)
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != http.StatusInternalServerError {
			t.Fatalf("business error status: got %d, want 500", resp.StatusCode)
		}
		if resp.Header.Get("X-Up-Err") != "boom" || string(body) != "up-500" {
			t.Fatalf("business error response not passed through: header=%q body=%q",
				resp.Header.Get("X-Up-Err"), string(body))
		}
		if !a.alive() {
			t.Fatal("a business 500 killed the ready process")
		}
		// the service is still ready: business error did not change state
		rrExpectReady(t, a, baseURL, "A")
	})

	// 2. startup failures exit non-zero, name the root cause and free resources.
	t.Run("startup failures are bounded and clean", func(t *testing.T) {
		failDir := t.TempDir()

		// truncated Caddyfile syntax
		trunc := rrWriteConfig(t, failDir, "trunc.Caddyfile",
			fmt.Sprintf("http://%s {\n\thandle /version {\n\t\theader X-Version A\n", siteHostPort))
		rrExpectStartupFailure(t, bin, trunc, failDir, siteHostPort, "syntax error", "unexpected token")
		rrAssertPortClosed(t, siteHostPort)

		// unknown directive
		unknown := rrWriteConfig(t, failDir, "unknown.Caddyfile",
			fmt.Sprintf("http://%s {\n\tbaddirective_xyz foo\n}\n", siteHostPort))
		rrExpectStartupFailure(t, bin, unknown, failDir, siteHostPort, "unrecognized directive")
		rrAssertPortClosed(t, siteHostPort)

		// listen address conflict: a plain listener without SO_REUSEPORT owns
		// the wildcard; caddy's bind must fail rather than silently share
		holder, err := net.Listen("tcp6", "[::]:"+fmt.Sprint(sitePort))
		if err != nil {
			// some sandboxes lack ipv6; fall back to the v4 wildcard - both
			// conflict with caddy's wildcard bind when reuse is absent
			holder, err = net.Listen("tcp", ":"+fmt.Sprint(sitePort))
			if err != nil {
				t.Skipf("cannot occupy site port for conflict test: %v", err)
			}
		}
		t.Cleanup(func() { holder.Close() })
		conflict := rrWriteConfig(t, failDir, "conflict.Caddyfile", rrCaddyfile(siteAddr, upstream.addr(), "A"))
		rrExpectStartupFailure(t, bin, conflict, failDir, siteHostPort,
			"address already in use", "bind", "listen")
		// the holder, not caddy, owns the port while it is alive
		holder.Close()

		// address is immediately reclaimable by a valid instance
		ok := rrStart(t, bin, cfgA, runDir)
		rrExpectReady(t, ok, baseURL, "A")
		_ = ok.terminate()
		ok.waitExit(t, 10*time.Second, "reclaim instance")

		// failed start followed by a successful start stays deterministic
		holder2, err := net.Listen("tcp6", "[::]:"+fmt.Sprint(sitePort))
		if err == nil {
			rrExpectStartupFailure(t, bin, conflict, failDir, siteHostPort,
				"address already in use", "bind", "listen")
			holder2.Close()
		}
		retry := rrStart(t, bin, cfgA, runDir)
		rrExpectReady(t, retry, baseURL, "A")
		_ = retry.terminate()
		retry.waitExit(t, 10*time.Second, "post-failure instance")
	})

	// 3. a request in flight across a stop/restart stays on the old
	// generation; new requests only ever see the new generation; the address
	// is reusable and repeated stops are deterministic.
	t.Run("held request across restart stays isolated", func(t *testing.T) {
		a := rrStart(t, bin, cfgA, runDir)
		rrExpectReady(t, a, baseURL, "A")

		holdClient := &http.Client{Timeout: 0}
		type holdResult struct {
			resp *http.Response
			rest []byte
			err  error
		}
		resultCh := make(chan holdResult, 1)
		go func() {
			resp, err := holdClient.Get(baseURL + "/hold")
			if err != nil {
				resultCh <- holdResult{err: err}
				return
			}
			prefix := make([]byte, len(rrHoldPrefix))
			if _, err := io.ReadFull(resp.Body, prefix); err != nil {
				resultCh <- holdResult{resp: resp, err: err}
				return
			}
			if string(prefix) != rrHoldPrefix {
				resultCh <- holdResult{resp: resp, err: fmt.Errorf("prefix: got %q", prefix)}
				return
			}
			rest, _ := io.ReadAll(resp.Body)
			resultCh <- holdResult{resp: resp, rest: rest}
		}()

		// wait for the A prefix proving the request is in flight on generation A
		waitUntil(t, func() bool { return upstream.heldCount() > 0 },
			"held request never parked at upstream")

		// stop A while the request is still open, then immediately start B on
		// the same address
		if err := a.terminate(); err != nil {
			t.Fatalf("SIGTERM A: %v", err)
		}
		b := rrStart(t, bin, cfgB, runDir)
		rrExpectReady(t, b, baseURL, "B")

		// new requests, on fresh and reused connections alike, only see B
		for i := 0; i < 8; i++ {
			resp, err := http.Get(baseURL + "/version")
			if err != nil {
				t.Fatalf("probe %d after restart: %v", i, err)
			}
			body, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			if resp.StatusCode != http.StatusOK ||
				resp.Header.Get("X-Version") != "B" ||
				string(body) != rrVersionB ||
				resp.Header.Get("X-Only-A") != "" {
				t.Fatalf("probe %d leaked prior generation / wrong contract: "+
					"status=%d X-Version=%q body=%q", i, resp.StatusCode,
					resp.Header.Get("X-Version"), string(body))
			}
		}

		// finish the parked upstream response; the client must receive exactly
		// the rest of generation A's answer, with no B content spliced in
		upstream.releaseAll()
		select {
		case res := <-resultCh:
			if res.err != nil {
				t.Fatalf("held request did not complete on generation A: %v", res.err)
			}
			if res.resp.StatusCode != http.StatusOK {
				t.Fatalf("held status: got %d, want 200", res.resp.StatusCode)
			}
			if res.resp.Header.Get("X-Hold-Marker") != "hold-A" {
				t.Fatalf("held marker: got %q, want hold-A", res.resp.Header.Get("X-Hold-Marker"))
			}
			if string(res.rest) != rrHoldSuffix {
				t.Fatalf("held suffix: got %q, want %q", res.rest, rrHoldSuffix)
			}
			if bytes.Contains(res.rest, []byte("B")) {
				t.Fatalf("held response spliced with B: %q", res.rest)
			}
		case <-time.After(15 * time.Second):
			t.Fatal("held request never completed after release")
		}

		// generation A now drains fully and exits cleanly; it never served B
		a.waitExit(t, 15*time.Second, "generation A after held request drained")

		// generation B shuts down cleanly; a repeat stop is a deterministic
		// no-op on the already-exited process
		if err := b.terminate(); err != nil {
			t.Fatalf("SIGTERM B: %v", err)
		}
		b.waitExit(t, 10*time.Second, "generation B")
		if err := b.terminate(); err == nil {
			t.Fatal("second SIGTERM on an exited process unexpectedly succeeded")
		}

		// the address is reusable again, immediately and repeatedly
		for round := 1; round <= 2; round++ {
			cfg := cfgA
			mark := "A"
			if round == 2 {
				cfg = cfgB
				mark = "B"
			}
			r := rrStart(t, bin, cfg, runDir)
			rrExpectReady(t, r, baseURL, mark)
			_ = r.terminate()
			r.waitExit(t, 10*time.Second, fmt.Sprintf("rebind round %d", round))
		}
	})
}

func (u *rrUpstream) heldCount() int {
	u.mu.Lock()
	defer u.mu.Unlock()
	return len(u.held)
}

func waitUntil(t *testing.T, cond func() bool, msg string) {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if cond() {
			return
		}
		time.Sleep(20 * time.Millisecond)
	}
	t.Fatal(msg)
}

