// rrCaddyfile builds a plaintext HTTP site on siteAddr whose /version answers
// 200 with X-Version: <mark> and the two-byte body "<mark>\n", and which
// proxies every other path (including /hold) to the test upstream. The admin
// endpoint is disabled so the foreground process is driven purely by signals.
func rrCaddyfile(siteAddr, upstream, mark string) string {
	body := mark + "\n" // Caddyfile unquoting turns \n into a real newline
	return fmt.Sprintf(`{
	skip_install_trust
	admin off
}
http://%s {
	handle /version {
		header X-Version %s
		respond %q
	}
	reverse_proxy %s
}
`, siteAddr, mark, body, upstream)
}

