// rrExpectReady polls until the full readiness contract holds at once: the
// process is alive, the port serves and /version answers 200, X-Version and
// the exact body. Process creation or a briefly-open port never count; a
// connection failure while the process is still starting is the startup
// ("not ready yet") phase, not an HTTP status.
func rrExpectReady(t *testing.T, p *rrProc, baseURL, mark string) {
	t.Helper()
	client := &http.Client{Timeout: 2 * time.Second}
	wantBody := mark + "\n"
	deadline := time.Now().Add(60 * time.Second)
	var lastOdd string
	for time.Now().Before(deadline) {
		if !p.alive() {
			t.Fatalf("process exited before becoming ready\n%s", p.tail(t))
		}
		resp, err := client.Get(baseURL + "/version")
		if err != nil {
			time.Sleep(50 * time.Millisecond) // not ready yet
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode == http.StatusOK &&
			resp.Header.Get("X-Version") == mark &&
			string(body) == wantBody {
			return
		}
		lastOdd = fmt.Sprintf("status=%d X-Version=%q body=%q",
			resp.StatusCode, resp.Header.Get("X-Version"), string(body))
		time.Sleep(50 * time.Millisecond)
	}
	t.Fatalf("readiness contract never held (200 + X-Version %q + %q): %s\n%s",
		mark, wantBody, lastOdd, p.tail(t))
}

